<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(17, 24, 39, 0.9);
        --panel-border: rgba(148, 163, 184, 0.18);
        --text: #e5e7eb;
        --muted: #94a3b8;
        --accent: #7c3aed;
        --accent-2: #22d3ee;
        --focus: #c4b5fd;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      html,
      body {
        margin: 0;
        min-height: 100%;
        background:
          radial-gradient(circle at top, rgba(124, 58, 237, 0.24), transparent 34%),
          radial-gradient(circle at right, rgba(34, 211, 238, 0.18), transparent 28%),
          var(--bg);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }

      body {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .app-shell {
        width: min(100%, 720px);
      }

      .card {
        background: linear-gradient(180deg, rgba(15, 23, 42, 0.96), rgba(17, 24, 39, 0.88));
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
        backdrop-filter: blur(16px);
      }

      .card__header {
        padding: 32px 32px 20px;
        border-bottom: 1px solid rgba(148, 163, 184, 0.12);
      }

      .eyebrow {
        margin: 0 0 10px;
        font-size: 0.85rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent-2);
      }

      h1 {
        margin: 0;
        font-size: clamp(1.7rem, 3vw, 2.3rem);
        line-height: 1.15;
      }

      .description {
        margin: 12px 0 0;
        color: var(--muted);
        max-width: 58ch;
      }

      .card__body {
        padding: 32px;
      }

      .form-field {
        display: grid;
        gap: 16px;
      }

      .question-text {
        margin: 0;
        font-size: 1.05rem;
        font-weight: 600;
      }

      .choices {
        display: grid;
        gap: 12px;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .choice {
        position: relative;
      }

      .choice input {
        position: absolute;
        inset: 0;
        opacity: 0;
        pointer-events: none;
      }

      .choice label {
        display: flex;
        align-items: center;
        gap: 14px;
        width: 100%;
        padding: 16px 18px;
        border-radius: 16px;
        border: 1px solid rgba(148, 163, 184, 0.16);
        background: rgba(15, 23, 42, 0.72);
        transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
        cursor: pointer;
      }

      .choice label::before {
        content: "";
        width: 18px;
        height: 18px;
        border-radius: 999px;
        border: 2px solid rgba(148, 163, 184, 0.55);
        box-shadow: inset 0 0 0 4px transparent;
        flex: none;
        transition: border-color 160ms ease, box-shadow 160ms ease;
      }

      .choice input:checked + label {
        border-color: rgba(124, 58, 237, 0.75);
        background: rgba(30, 41, 59, 0.95);
        box-shadow: 0 10px 24px rgba(124, 58, 237, 0.16);
      }

      .choice input:checked + label::before {
        border-color: var(--accent);
        box-shadow: inset 0 0 0 5px var(--accent);
      }

      .choice input:focus-visible + label {
        outline: 3px solid rgba(196, 181, 253, 0.42);
        outline-offset: 2px;
      }

      .choice label:hover {
        transform: translateY(-1px);
        border-color: rgba(124, 58, 237, 0.45);
      }

      .actions {
        margin-top: 28px;
        display: flex;
        justify-content: flex-end;
      }

      .submit-button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        color: white;
        font: inherit;
        font-weight: 700;
        background: linear-gradient(135deg, var(--accent), #4f46e5);
        box-shadow: 0 16px 34px rgba(79, 70, 229, 0.32);
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 38px rgba(79, 70, 229, 0.38);
      }

      .submit-button:focus-visible {
        outline: 3px solid rgba(196, 181, 253, 0.45);
        outline-offset: 3px;
      }

      .helper-text {
        margin: 14px 0 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .status {
        margin-top: 18px;
        min-height: 1.5rem;
        color: #a7f3d0;
        font-weight: 600;
      }

      @media (max-width: 640px) {
        .card__header,
        .card__body {
          padding-left: 20px;
          padding-right: 20px;
        }

        .actions {
          justify-content: stretch;
        }

        .submit-button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main id="root" class="app-shell" aria-live="polite"></main>

    <script>
      function NotificationQuestion() {
        return `
          <section class="card" aria-labelledby="notification-heading">
            <header class="card__header">
              <p class="eyebrow">Preferences</p>
              <h1 id="notification-heading">Notification delivery</h1>
              <p class="description">Choose one way you would prefer to receive notifications.</p>
            </header>
            <div class="card__body">
              <form id="notification-form">
                <div class="form-field">
                  <p class="question-text" id="notification-question">How do you prefer to receive notifications?</p>
                  <div role="radiogroup" aria-labelledby="notification-question">
                    <ul class="choices">
                      <li class="choice">
                        <input type="radio" id="email" name="notification-method" value="Email" required />
                        <label for="email">Email</label>
                      </li>
                      <li class="choice">
                        <input type="radio" id="sms" name="notification-method" value="SMS" />
                        <label for="sms">SMS</label>
                      </li>
                      <li class="choice">
                        <input type="radio" id="push" name="notification-method" value="Push Notifications" />
                        <label for="push">Push Notifications</label>
                      </li>
                    </ul>
                  </div>
                  <div class="actions">
                    <button class="submit-button" type="submit">Submit</button>
                  </div>
                  <p class="helper-text">Only one answer can be selected.</p>
                  <p class="status" id="form-status" role="status" aria-atomic="true"></p>
                </div>
              </form>
            </div>
          </section>
        `;
      }

      function App() {
        return `
          ${NotificationQuestion()}
        `;
      }

      const root = document.getElementById("root");
      root.innerHTML = App();

      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const selected = form.querySelector('input[name="notification-method"]:checked');
        if (!selected) {
          status.textContent = "Please select a notification preference before submitting.";
          return;
        }

        status.textContent = `Saved preference: ${selected.value}.`;
      });
    </script>
  </body>
</html>
